import face_recog as fr
import os

def find_criminals(img_path):
    known_crim = fr.load_img("known_criminals")
    unk_img = fr.load_img(img_path)
    crim_faces = fr.get_faces(known_crim)
    unk_faces = fr.get_faces(unk_img)

    for face in unk_faces:
        match = fr.compare(face, crim_faces)
        if match:
            print("Criminal found")
        else:
            print("No criminal")

img_dir = "race_pics"
for pic in os.listdir(img_dir):
    if pic.endswith("jpg"):
        find_criminals(pic)
